-- KwanPro local MSSQL schema
-- Generated by hand from ../entities/* per the base44-to-local workflow.
-- Table names match backend/server.js TABLE_MAP. Apply to your local MSSQL
-- instance before starting the backend.

IF OBJECT_ID('Users', 'U') IS NULL
CREATE TABLE Users (
    id            NVARCHAR(36)  NOT NULL PRIMARY KEY,
    email         NVARCHAR(255) NOT NULL UNIQUE,
    password_hash NVARCHAR(255) NOT NULL,
    full_name     NVARCHAR(255) NULL,
    role          NVARCHAR(50)  NOT NULL DEFAULT 'user',
    created_date  DATETIME2     NOT NULL DEFAULT GETDATE(),
    updated_date  DATETIME2     NULL
);

IF OBJECT_ID('Announcements', 'U') IS NULL
CREATE TABLE Announcements (
    id           NVARCHAR(36)  NOT NULL PRIMARY KEY,
    title        NVARCHAR(255) NOT NULL,
    content      NVARCHAR(MAX) NOT NULL,
    target_belt  NVARCHAR(255) NOT NULL DEFAULT 'All',
    is_published BIT           NOT NULL DEFAULT 1,
    event_date   DATETIME2     NULL,
    type         NVARCHAR(255) NOT NULL DEFAULT 'announcement',
    created_date DATETIME2     NOT NULL DEFAULT GETDATE(),
    updated_date DATETIME2     NULL
);

IF OBJECT_ID('Attendance', 'U') IS NULL
CREATE TABLE Attendance (
    id            NVARCHAR(36)  NOT NULL PRIMARY KEY,
    student_id    NVARCHAR(255) NOT NULL,
    student_name  NVARCHAR(255) NULL,
    class_id      NVARCHAR(255) NOT NULL,
    class_name    NVARCHAR(255) NULL,
    date          DATETIME2     NOT NULL,
    belt_at_time  NVARCHAR(255) NULL,
    notes         NVARCHAR(MAX) NULL,
    created_date  DATETIME2     NOT NULL DEFAULT GETDATE(),
    updated_date  DATETIME2     NULL
);

IF OBJECT_ID('BeltLevels', 'U') IS NULL
CREATE TABLE BeltLevels (
    id             NVARCHAR(36)  NOT NULL PRIMARY KEY,
    name           NVARCHAR(255) NOT NULL,
    color_hex      NVARCHAR(255) NOT NULL,
    text_color_hex NVARCHAR(255) NOT NULL DEFAULT '#000000',
    [order]        FLOAT         NOT NULL,
    is_active      BIT           NOT NULL DEFAULT 1,
    created_date   DATETIME2     NOT NULL DEFAULT GETDATE(),
    updated_date   DATETIME2     NULL
);

IF OBJECT_ID('BeltRequirements', 'U') IS NULL
CREATE TABLE BeltRequirements (
    id               NVARCHAR(36)  NOT NULL PRIMARY KEY,
    belt             NVARCHAR(255) NOT NULL,
    required_classes FLOAT         NOT NULL,
    minimum_months   FLOAT         NOT NULL,
    required_skills  NVARCHAR(MAX) NULL,
    description      NVARCHAR(MAX) NULL,
    created_date     DATETIME2     NOT NULL DEFAULT GETDATE(),
    updated_date     DATETIME2     NULL
);

IF OBJECT_ID('Classes', 'U') IS NULL
CREATE TABLE Classes (
    id              NVARCHAR(36)  NOT NULL PRIMARY KEY,
    name            NVARCHAR(255) NOT NULL,
    level           NVARCHAR(255) NOT NULL,
    instructor_name NVARCHAR(255) NULL,
    day_of_week     NVARCHAR(255) NOT NULL,
    start_time      NVARCHAR(255) NOT NULL,
    end_time        NVARCHAR(255) NULL,
    capacity        FLOAT         NULL,
    belt_min        NVARCHAR(255) NULL,
    belt_max        NVARCHAR(255) NULL,
    is_active       BIT           NOT NULL DEFAULT 1,
    created_date    DATETIME2     NOT NULL DEFAULT GETDATE(),
    updated_date    DATETIME2     NULL
);

IF OBJECT_ID('ClassBookings', 'U') IS NULL
CREATE TABLE ClassBookings (
    id           NVARCHAR(36)  NOT NULL PRIMARY KEY,
    class_id     NVARCHAR(255) NOT NULL,
    class_name   NVARCHAR(255) NULL,
    student_id   NVARCHAR(255) NOT NULL,
    student_name NVARCHAR(255) NULL,
    status       NVARCHAR(255) NOT NULL DEFAULT 'booked',
    created_date DATETIME2     NOT NULL DEFAULT GETDATE(),
    updated_date DATETIME2     NULL
);

IF OBJECT_ID('InventoryItems', 'U') IS NULL
CREATE TABLE InventoryItems (
    id                  NVARCHAR(36)  NOT NULL PRIMARY KEY,
    name                NVARCHAR(255) NOT NULL,
    category            NVARCHAR(255) NOT NULL,
    sku                 NVARCHAR(255) NULL,
    price               FLOAT         NULL,
    quantity            FLOAT         NOT NULL DEFAULT 0,
    low_stock_threshold FLOAT         NOT NULL DEFAULT 5,
    description         NVARCHAR(MAX) NULL,
    is_active           BIT           NOT NULL DEFAULT 1,
    created_date        DATETIME2     NOT NULL DEFAULT GETDATE(),
    updated_date        DATETIME2     NULL
);

IF OBJECT_ID('InventoryPurchases', 'U') IS NULL
CREATE TABLE InventoryPurchases (
    id            NVARCHAR(36)  NOT NULL PRIMARY KEY,
    item_id       NVARCHAR(255) NOT NULL,
    item_name     NVARCHAR(255) NULL,
    student_id    NVARCHAR(255) NULL,
    student_name  NVARCHAR(255) NULL,
    quantity      FLOAT         NOT NULL DEFAULT 1,
    unit_price    FLOAT         NULL,
    total_price   FLOAT         NULL,
    purchase_date DATETIME2     NOT NULL,
    notes         NVARCHAR(MAX) NULL,
    created_date  DATETIME2     NOT NULL DEFAULT GETDATE(),
    updated_date  DATETIME2     NULL
);

IF OBJECT_ID('Payments', 'U') IS NULL
CREATE TABLE Payments (
    id           NVARCHAR(36)  NOT NULL PRIMARY KEY,
    student_id   NVARCHAR(255) NOT NULL,
    student_name NVARCHAR(255) NULL,
    amount       FLOAT         NOT NULL,
    due_date     DATETIME2     NOT NULL,
    paid_date    DATETIME2     NULL,
    status       NVARCHAR(255) NOT NULL DEFAULT 'pending',
    plan         NVARCHAR(255) NULL,
    notes        NVARCHAR(MAX) NULL,
    created_date DATETIME2     NOT NULL DEFAULT GETDATE(),
    updated_date DATETIME2     NULL
);

IF OBJECT_ID('Promotions', 'U') IS NULL
CREATE TABLE Promotions (
    id                NVARCHAR(36)  NOT NULL PRIMARY KEY,
    student_id        NVARCHAR(255) NOT NULL,
    student_name      NVARCHAR(255) NULL,
    from_belt         NVARCHAR(255) NOT NULL,
    to_belt           NVARCHAR(255) NOT NULL,
    promotion_date    DATETIME2     NOT NULL,
    test_result       NVARCHAR(255) NULL,
    instructor_notes  NVARCHAR(MAX) NULL,
    classes_completed FLOAT         NULL,
    created_date      DATETIME2     NOT NULL DEFAULT GETDATE(),
    updated_date      DATETIME2     NULL
);

IF OBJECT_ID('SparringMatches', 'U') IS NULL
CREATE TABLE SparringMatches (
    id                  NVARCHAR(36)  NOT NULL PRIMARY KEY,
    date                DATETIME2     NOT NULL,
    student1_id         NVARCHAR(255) NOT NULL,
    student1_name       NVARCHAR(255) NULL,
    student1_belt       NVARCHAR(255) NULL,
    student2_id         NVARCHAR(255) NOT NULL,
    student2_name       NVARCHAR(255) NULL,
    student2_belt       NVARCHAR(255) NULL,
    winner_id           NVARCHAR(255) NULL,
    winner_name         NVARCHAR(255) NULL,
    result              NVARCHAR(255) NOT NULL DEFAULT 'draw',
    instructor_feedback NVARCHAR(MAX) NULL,
    student1_feedback   NVARCHAR(MAX) NULL,
    student2_feedback   NVARCHAR(MAX) NULL,
    class_id            NVARCHAR(255) NULL,
    class_name          NVARCHAR(255) NULL,
    created_date        DATETIME2     NOT NULL DEFAULT GETDATE(),
    updated_date        DATETIME2     NULL
);

IF OBJECT_ID('Students', 'U') IS NULL
CREATE TABLE Students (
    id                       NVARCHAR(36)  NOT NULL PRIMARY KEY,
    full_name                NVARCHAR(255) NOT NULL,
    email                    NVARCHAR(255) NULL,
    phone                    NVARCHAR(255) NULL,
    date_of_birth            DATETIME2     NULL,
    emergency_contact_name   NVARCHAR(255) NULL,
    emergency_contact_phone  NVARCHAR(255) NULL,
    current_belt             NVARCHAR(255) NOT NULL DEFAULT 'White',
    classes_in_current_belt  FLOAT         NOT NULL DEFAULT 0,
    belt_start_date          DATETIME2     NULL,
    total_classes_attended   FLOAT         NOT NULL DEFAULT 0,
    membership_status        NVARCHAR(255) NOT NULL DEFAULT 'active',
    membership_plan          NVARCHAR(255) NOT NULL DEFAULT 'monthly',
    instructor_notes         NVARCHAR(MAX) NULL,
    photo_url                NVARCHAR(MAX) NULL,
    join_date                DATETIME2     NULL,
    stripes                  FLOAT         NOT NULL DEFAULT 0,
    eligible_for_testing     BIT           NOT NULL DEFAULT 0,
    instructor_approved      BIT           NOT NULL DEFAULT 0,
    created_date             DATETIME2     NOT NULL DEFAULT GETDATE(),
    updated_date             DATETIME2     NULL
);
